#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-tell-a-dead-server-from-a-missing-file. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
cat > stop-and-fetch.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Starts a surl on the port in the first argument, fetches from it, stops it, and fetches
# again, printing the status and curl's exit code each time. The running server holds
# site, so this one serves a copy.
port=$1
cp -r site live
surl -s --directory live http://127.0.0.1:$port/ >/dev/null 2>&1 &
pid=$!
until curl -s -o /dev/null http://127.0.0.1:$port/hello.txt; do sleep 0.2; done
curl -s -w "%{http_code} %{exitcode}\n" -o /dev/null http://127.0.0.1:$port/hello.txt
kill $pid
# Give the port a moment to close, then ask once more.
while curl -s -o /dev/null http://127.0.0.1:$port/hello.txt; do sleep 0.2; done
curl -s -w "%{http_code} %{exitcode}\n" -o /dev/null http://127.0.0.1:$port/hello.txt
exit 0
EOF
curl -s -w "%{exitcode} %{errormsg}\n" -o /dev/null http://127.0.0.1:8081/hello.txt || true
